local BasketWeaver = {}
local PRODUCTS = {
    basket = { name = "Košara", willowCost = 3, time = 2, cost = 15, capacity = 20, happiness = 1, description = "Preprosta košara." },
    hamper = { name = "Velika košara", willowCost = 6, time = 4, cost = 40, capacity = 50, description = "Za shranjevanje." },
    wicker_chair = { name = "Pleteni stol", willowCost = 10, time = 7, cost = 80, happiness = 3, description = "Pleteni stol iz vrbe." },
    fish_trap = { name = "Ribja past", willowCost = 4, time = 3, cost = 30, description = "Za lovljenje rib." },
    cradle = { name = "Zibka", willowCost = 8, time = 5, cost = 60, happiness = 4, description = "Pletena zibka." },
    royal_basket = { name = "Kraljevska košara", willowCost = 12, silkCost = 2, goldCost = 1, time = 10, cost = 200, happiness = 8, prestige = 10, description = "Luksuzna košara s svilo in zlatom." },
}
local BUILDINGS = {
    workshop = { name = "Košarska delavnica", cost = { gold = 100, wood = 50 }, upkeep = 2, qualityBonus = 5 },
    willow_garden = { name = "Vrbovje", cost = { gold = 150, wood = 50 }, upkeep = 3, willowProduction = 5 },
    wicker_studio = { name = "Pletiljski atelje", cost = { gold = 800, wood = 200, stone = 100 }, upkeep = 20, qualityBonus = 20 },
    royal_basketry = { name = "Kraljevska košararna", cost = { gold = 2500, wood = 400, stone = 500, gold = 30 }, upkeep = 50, qualityBonus = 35, prestigeBonus = 15 },
}
BasketWeaver.willowStock = 20; BasketWeaver.silkStock = 3; BasketWeaver.goldStock = 2
BasketWeaver.productStock = {}; BasketWeaver.buildings = {}; BasketWeaver.weaver = nil; BasketWeaver.activeMaking = {}; BasketWeaver.totalProducts = 0; BasketWeaver.dayTimer = 0
function BasketWeaver.init() BasketWeaver.willowStock=20; BasketWeaver.silkStock=3; BasketWeaver.goldStock=2; BasketWeaver.productStock={}; BasketWeaver.buildings={}; BasketWeaver.weaver=nil; BasketWeaver.activeMaking={}; BasketWeaver.totalProducts=0; BasketWeaver.dayTimer=0; print("[BasketWeaver] Royal Basket Weaver & Wickerwork System initialized (6 products, 4 buildings)") end
function BasketWeaver.hireWeaver(n,s) s=s or math.random(30,75); local c=150+s*3; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BasketWeaver.weaver={name=n or ("Košarar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Košarar najet: %s (spretnost: %d)",BasketWeaver.weaver.name,s),"success") end; return true end
function BasketWeaver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BasketWeaver.build(id) local ok,e=BasketWeaver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BasketWeaver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BasketWeaver.getQualityBonus() local b=0; for _,bd in ipairs(BasketWeaver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BasketWeaver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.willowCost and BasketWeaver.willowStock<(d.willowCost or 0) then return false,"Premalo vrbe" end; if d.silkCost and BasketWeaver.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.goldCost and BasketWeaver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #BasketWeaver.buildings==0 then return false,"Potrebna delavnica" end; if not BasketWeaver.weaver then return false,"Potreben košarar" end; return true end
function BasketWeaver.make(pt) local ok,e=BasketWeaver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.willowCost then BasketWeaver.willowStock=BasketWeaver.willowStock-d.willowCost end; if d.silkCost then BasketWeaver.silkStock=BasketWeaver.silkStock-d.silkCost end; if d.goldCost then BasketWeaver.goldStock=BasketWeaver.goldStock-d.goldCost end; local t=d.time; if BasketWeaver.weaver then t=math.max(1,t-math.floor(BasketWeaver.weaver.skill/15)) end; table.insert(BasketWeaver.activeMaking,{id="basket_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,capacity=d.capacity or 0,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %s (%d dni)",d.name,t),"info") end; return true end
function BasketWeaver.completeMaking(m) local q=1.0+(BasketWeaver.getQualityBonus()/100); if BasketWeaver.weaver then q=q+(BasketWeaver.weaver.skill/200) end; q=math.min(2.0,q); BasketWeaver.productStock[m.productType]=(BasketWeaver.productStock[m.productType] or 0)+1; BasketWeaver.totalProducts=BasketWeaver.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if BasketWeaver.weaver then BasketWeaver.weaver.itemsMade=BasketWeaver.weaver.itemsMade+1; if math.random()<0.15 then BasketWeaver.weaver.skill=math.min(100,BasketWeaver.weaver.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Košara izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function BasketWeaver.update(dt) if not _G.state then return end; BasketWeaver.dayTimer=BasketWeaver.dayTimer+dt; if BasketWeaver.dayTimer>=30 then BasketWeaver.dayTimer=0; for i=#BasketWeaver.activeMaking,1,-1 do local m=BasketWeaver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BasketWeaver.completeMaking(m); table.remove(BasketWeaver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BasketWeaver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BasketWeaver.weaver then tu=tu+4 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BasketWeaver.getStats() return {willowStock=BasketWeaver.willowStock,silkStock=BasketWeaver.silkStock,goldStock=BasketWeaver.goldStock,productStock=BasketWeaver.productStock,numBuildings=#BasketWeaver.buildings,hasWeaver=BasketWeaver.weaver~=nil,weaverName=BasketWeaver.weaver and BasketWeaver.weaver.name or "—",weaverSkill=BasketWeaver.weaver and BasketWeaver.weaver.skill or 0,activeMaking=#BasketWeaver.activeMaking,totalProducts=BasketWeaver.totalProducts} end
return BasketWeaver
